<script lang="ts">
 import {onMount} from 'svelte';
 import {page} from '$app/state';
 import {goto} from '$app/navigation';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {noticeText,failureCode} from '$lib/shared/presentation/copy';
 import {queueKinds,filterWork,loadedCount,workPageContext,type WorkQueueGateway,type WorkPage,type QueueKind} from '../application/work-queue';
 import Icon from '$lib/shared/presentation/ui/Icon.svelte';
 let {gateway,actor}:{gateway:WorkQueueGateway;actor:string}=$props();const {locale}=useLocale();
 const names=$derived({publications:text($locale,'Жарияланымдар','Публикации'),changes:text($locale,'Тайтл өзгерістері','Правки тайтлов'),projects:text($locale,'Жобалар','Проекты'),teams:text($locale,'Командалар','Команды'),reports:text($locale,'Шағымдар','Жалобы')});
 const kind=$derived(queueKinds.includes(page.url.searchParams.get('queue') as QueueKind)?page.url.searchParams.get('queue') as QueueKind:'publications');
 let pages=$state<Partial<Record<QueueKind,WorkPage>>>({}),errors=$state<Partial<Record<QueueKind,string>>>({}),busy=$state<Partial<Record<QueueKind,boolean>>>({publications:true,changes:true,projects:true,teams:true,reports:true}),query=$state(''),team=$state('');let generation=0;let depths:Partial<Record<QueueKind,number>>={};
 const current=$derived(pages[kind]);const items=$derived(filterWork(current?.items||[],query,team));
 const teams=$derived([...new Set((current?.items||[]).map(item=>item.team).filter(Boolean))]);
 const total=$derived(queueKinds.every(key=>pages[key])?queueKinds.reduce((sum,key)=>sum+(pages[key]?.items.length||0),0)+ (queueKinds.some(key=>pages[key]?.next)?'+':''):'—');
 async function load(key:QueueKind,append=false){const run=generation;busy[key]=true;errors[key]='';try{const depth=append?(depths[key]||1)+1:1;const result=workPageContext(await gateway.list(key,actor,append?pages[key]?.next:''),depth);if(run===generation){depths[key]=depth;pages[key]={items:append?[...(pages[key]?.items||[]),...result.items]:result.items,next:result.next};}}catch(e){if(run===generation)errors[key]=failureCode(e);}finally{if(run===generation)busy[key]=false;}}
 onMount(()=>{generation++;for(const key of queueKinds)void load(key);return()=>{generation++;};});
 function choose(key:QueueKind){query='';team='';void goto('/admin?queue='+key,{noScroll:true,keepFocus:true});}
 $effect(()=>{kind;query='';team='';});
</script>
<svelte:head><title>{text($locale,'Жұмыс кезегі','Рабочая очередь')} — Qmanga</title></svelte:head>
<div class="queue-heading"><div><h1>{text($locale,'Жұмыс кезегі','Рабочая очередь')}</h1><p>{text($locale,'Шешіміңізді күтіп тұрған материалдар.','Все материалы, которым нужно ваше решение.')}</p></div>{#if items[0]}<a class="button primary" href={items[0].href}>{text($locale,'Тексеруді бастау','Начать проверку')}</a>{/if}</div>
<dl class="queue-stats"><div><dd>{total}</dd><dt>{text($locale,'Шешімді күтеді','Ожидают решения')}</dt></div><div><dd>{loadedCount(pages.publications||null)}</dd><dt>{names.publications}</dt></div><div><dd>{loadedCount(pages.reports||null)}</dd><dt>{names.reports}</dt></div><div><dd>{loadedCount(pages.teams||null)}</dd><dt>{names.teams}</dt></div></dl>
<nav class="queue-tabs" aria-label={text($locale,'Материал түрі','Вид материала')}>{#each queueKinds as key}<button aria-current={kind===key?'page':undefined} onclick={()=>choose(key)}>{names[key]} <span>{loadedCount(pages[key]||null)}</span>{#if errors[key]}<Icon name="flag" size={14}/>{/if}</button>{/each}</nav>
<div class="queue-tools"><label><span>{text($locale,'Жүктелген материалдардан іздеу','Поиск по загруженным материалам')}</span><input type="search" bind:value={query} placeholder={text($locale,'Тайтл, тарау немесе команда','Тайтл, глава или команда')}/></label><label><span>{text($locale,'Команда','Команда')}</span><select bind:value={team}><option value="">{text($locale,'Барлық командалар','Все команды')}</option>{#each teams as value}<option>{value}</option>{/each}</select></label><button class="button subtle" disabled={busy[kind]} onclick={()=>load(kind)}><Icon name="reset" size={16}/>{text($locale,'Жаңарту','Обновить')}</button></div>
{#if errors[kind]}<p role="alert" class="form-message">{noticeText($locale,errors[kind]||'')}</p>{/if}
{#if busy[kind]&&!current}<p role="status">{text($locale,'Кезек жүктелуде…','Загружаем очередь…')}</p>{:else}
<div class="work-table"><div class="table-heading"><span>{text($locale,'Материал','Материал')}</span><span>{text($locale,'Команда','Команда')}</span><span>{text($locale,'Берілді','Подано')}</span><span>{text($locale,'Әрекет','Действие')}</span></div>
{#each items as item (item.id)}<article><div class="material"><span class="material-initial" aria-hidden="true">{Array.from(item.title)[0]||'Q'}</span><div><h2><a href={item.href}>{item.title}</a></h2><p title={item.description}>{kind==='publications'?text($locale,'Тарау ','Глава '):''}{item.description}</p></div></div><p class="team">{item.team||'—'}</p><p class="submitted">{item.createdAt?new Date(item.createdAt).toLocaleDateString($locale==='ru'?'ru-RU':'kk-KZ',{timeZone:'UTC'}):'—'}</p><a class="open" href={item.href}>{text($locale,'Ашу','Открыть')}<Icon name="right" size={16}/></a></article>{:else}{#if !errors[kind]}<div class="queue-empty"><Icon name="check" size={28}/><h2>{query||team?text($locale,'Ештеңе табылмады','Ничего не найдено'):current?.next?text($locale,'Жүктелген бөлікте материал жоқ','В загруженной части нет материалов'):text($locale,'Кезек бос','Очередь пуста')}</h2><p>{query||team?text($locale,'Іздеуді немесе команданы өзгертіңіз.','Измени запрос или команду.'):text($locale,'Жаңа материалдар осы жерде пайда болады.','Новые материалы появятся здесь.')}</p></div>{/if}{/each}
<footer><span>{text($locale,'Жүктелген: ','Загружено: ')}{loadedCount(current||null)}</span>{#if current?.next}<button class="button subtle" disabled={busy[kind]} onclick={()=>load(kind,true)}>{text($locale,'Тағы жүктеу','Загрузить ещё')}</button>{/if}<a href={kind==='publications'?'/admin/moderation':kind==='changes'?'/moderation/title-changes':kind==='projects'?'/admin/requests':kind==='teams'?'/admin/teams':'/admin/reports'}>{text($locale,'Толық кезек','Полная очередь')} →</a></footer></div>
{/if}
<style>
 .queue-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;margin-bottom:24px}.queue-heading h1{font-size:28px;letter-spacing:-.4px}.queue-heading p{font-size:14px;color:var(--muted);margin-top:8px}.queue-stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:0 0 24px}.queue-stats>div{padding:18px 20px;background:var(--panel);border:1px solid var(--line);border-radius:12px;min-width:0}.queue-stats dd{font-size:30px;line-height:1.3;font-weight:650;margin:0 0 6px}.queue-stats>div:first-child dd{color:var(--accent)}.queue-stats dt{font-size:13px}.queue-tabs{display:flex;gap:8px;overflow:auto;margin:0 0 20px}.queue-tabs button{display:flex;gap:8px;align-items:center;min-height:44px;white-space:nowrap;padding:8px 14px;border:0;background:none;border-radius:8px;color:var(--muted);font-size:13px}.queue-tabs [aria-current]{background:var(--raised);color:var(--accent)}.queue-tabs span{font-size:11px}.queue-tools{display:flex;align-items:end;flex-wrap:wrap;gap:12px;margin-bottom:24px}.queue-tools label{display:grid;gap:5px;min-width:0;flex:1 1 190px;font-size:11px;color:var(--muted)}.queue-tools label:first-child{flex-grow:2}.queue-tools input,.queue-tools select{width:100%;font-size:13px}.work-table{border:1px solid var(--line);border-radius:12px;overflow:hidden}.table-heading{display:none}article{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px 16px;padding:14px 16px;border-bottom:1px solid var(--line);align-items:center;min-width:0}.material{display:flex;gap:12px;align-items:center;min-width:0;grid-column:1/-1}.material>div{min-width:0}.material-initial{display:grid;place-items:center;width:36px;height:48px;border-radius:6px;background:var(--raised);color:var(--accent);font-size:20px;flex:none}.material h2{font-size:14px;font-weight:550;overflow-wrap:anywhere}.material h2 a{display:flex;align-items:center;min-height:44px}.material p{font-size:12px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}.team,.submitted{font-size:12px;color:var(--muted);overflow-wrap:anywhere}.submitted{display:none}.open{display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:44px;font-size:13px}footer{display:flex;gap:12px;align-items:center;flex-wrap:wrap;padding:16px 20px;font-size:12px;color:var(--muted)}footer>a{margin-left:auto;min-height:44px;display:flex;align-items:center}.queue-empty{padding:40px 20px;color:var(--muted);text-align:center}.queue-empty :global(svg){margin-inline:auto}.queue-empty h2{font-size:18px;margin:12px 0 6px;color:var(--text)}.queue-empty p{font-size:13px}
 @media(min-width:760px){.queue-stats{grid-template-columns:repeat(4,minmax(0,1fr));gap:20px}.table-heading,article{grid-template-columns:minmax(0,2fr) minmax(0,1fr) 110px 110px}.table-heading{display:grid;padding:14px 20px;background:var(--raised);color:var(--muted);font-size:11px;text-transform:uppercase;gap:16px}.material{grid-column:auto}.submitted{display:block}article{padding:14px 20px}.material h2 a{min-height:28px}.team{color:var(--text);font-size:13px}}
</style>
